export const CODE: Record<string, string> = {
  "brain.py": "\"\"\"14-agent brain - a capability-routed supervisor agent. `python brain.py` runs it.\n\n    python brain.py                                   # the brain, plus a REPL\n    python brain.py \"Research the Collatz conjecture, then write a Python\n                     CLI that prints the Collatz sequence for N\"\n    python brain.py --stream \"...\"                    # watch the chain live\n    python brain.py memory                            # what it remembers\n\n    open http://127.0.0.1:8000                        # the chat window\n\nLayout\n------\n    config.py                 shared settings (HF router, token, paths)\n    neurons/model/            planner, research, coding  (stock LLM Neurons;\n                              behaviour via @before_task / @detects_output;\n                              chain declared as @AXON.host.on_agent_output,\n                              applied to the hosting Dendrite on announce)\n    effector/                 websearch, fetch, clock, files  (tools - real\n                              Effectors over the stock MCP servers,\n                              TOOL_CALL/TOOL_RESULT serviced by the SDK the\n                              moment they're attached)\n    engram/agent_memory.py    the store + its @ENGRAM.host.on_imprint_signal\n    receptors/                terminal + chat  (the interfaces)\n    brain.py                  deployment: which node hosts what\n\nModules under those four folders declare *behaviour*; this file owns\n*deployment* - which node hosts what, roles, ids, and which interfaces are\nexposed. Nothing here is \"run\" but the brain itself: ``run_brain`` starts\nevery node, serves every interface any of them mounts, and stops them on\nthe way out. There is no app.py and no cli.py - an interface is a\ncomponent, so starting the brain starts its interfaces, and brain.py takes\nno flags of its own (everything after ``python brain.py`` belongs to the\nterminal Receptor).\n\nOne node, one Dendrite\n----------------------\nEach component gets its own Dendrite rather than sharing a \"worker\". A\nDendrite is a node's attachment to the synapse - its identity, its\nsubscriptions, its REGISTER - so one per node is what makes each of them\nseparately addressable, separately visible in Prism, and movable into its\nown process by deleting one line below. Nothing about the modules changes\nwhen it goes distributed; only which process calls which builder.\n\nThere is NO supervisor loop - and no tool protocol anywhere either.\nA Receptor dispatches ONE capability-routed TASK (``[\"planner\"]``) and\nwaits for the trace's FINAL. Everything else is the Dendrites'\nresponsibility - they pick relevant Signals up and create more TASKs:\n\n    planner-node   @on_agent_output(neuron=\"planner\")   -> TASK [\"research\"|\"coding\"],\n                                                           or assemble + imprint + FINAL\n    research-node  @on_agent_output(neuron=\"research\")  -> TASK [\"planner\"] (next step)\n    coding-node    @on_agent_output(neuron=\"coding\")    -> TASK [\"planner\"] (next step)\n    memory-node    @ENGRAM.host.on_imprint_signal       -> mirror \"answer\" to disk\n\nChain state rides the TASK inputs (echoed through outputs); progress is\nrecalled from the engram, not held by any node. All chain TASKs share the\nrun's trace so its FINAL resolves the interface's Pathway. Tool invocations\nare NOT tasks: they ride TOOL_CALL -> TOOL_RESULT signal pairs, serviced\nnatively by whichever Dendrite has ``attach_effector``-ed the target\nEffector - calls fired from Axon hooks inherit the containing TASK's trace.\nTool calls are NOT role-gated (only TASK/STOP are), so ANY node may call\nits tools; the agent nodes are role=\"orchestrator\" only because their chain\nhandlers dispatch the next TASK. Agents own their tools -\n``dendrite.call_tool(effector_id=...)`` from their own hooks:\n\n    planner  -> clock-effector              research -> websearch-, fetch-effector\n    coding   -> files-effector              memory-node -> files-effector\n\nSet SYNAPSE_URL to a running synapse to split this across processes - and\nto watch the chain live:  cosmo prism --tail --url=$SYNAPSE_URL -n agent\n\"\"\"\nfrom __future__ import annotations\n\nimport asyncio\nimport contextlib\nimport os\nimport signal\n\nfrom cosmonapse import (Dendrite, MemoryRegistryStore, MemorySynapse,\n                        connect_synapse, run_brain)\n\nfrom config import NAMESPACE\nfrom effector import clock, fetch, files, websearch\nfrom engram import agent_memory\nfrom neurons.model import coding, planner, research\nfrom receptors import chat, terminal\n\n# The agents' hooks AND their chain handlers are declared in their modules\n# (@AXON.before_task / @AXON.detects_output / @AXON.host.on_agent_output),\n# so an agent node is one line here regardless of how much it does.\nAGENT_AXONS = [planner.AXON, research.AXON, coding.AXON]\n\n\ndef build_memory(synapse) -> Dendrite:\n    \"\"\"The Engram that remembers - services RECALL and IMPRINT.\n\n    role=\"worker\" and yet it calls the files Effector: TOOL_CALLs are not\n    role-gated, only TASK and STOP are. Nothing needs orchestrator rights\n    to use a tool.\n    \"\"\"\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"memory-node\", role=\"worker\")\n    node.attach_engram(agent_memory.ENGRAM)   # @ENGRAM.host.on_* replayed here\n    return node\n\n\ndef build_agents(synapse) -> list[Dendrite]:\n    \"\"\"One node per agent Neuron - planner, research, coding.\n\n    role=\"orchestrator\" because each one's chain handler dispatches the next\n    TASK. The Neurons themselves never decide what work exists; the hosting\n    Dendrite does, off the output Signal.\n    \"\"\"\n    nodes = []\n    for axon in AGENT_AXONS:\n        node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                        dendrite_id=f\"{axon.neuron_id}-node\",\n                        role=\"orchestrator\")\n        node.attach_axon(axon)                # @AXON.host.on_* on announce\n        nodes.append(node)\n    return nodes\n\n\ndef build_web(synapse) -> Dendrite:\n    \"\"\"websearch + fetch on ONE node - two Effectors, one attachment point.\n\n    The Dendrite routes each TOOL_CALL to the right Effector by directed\n    id/kind on its own; no host-decorator filtering needed. A Dendrite\n    hosting several components is always available - it just costs the\n    independence the other builders keep.\n    \"\"\"\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"web-node\", role=\"worker\")\n    for effector in (websearch.EFFECTOR, fetch.EFFECTOR):\n        node.attach_effector(effector)\n    return node\n\n\ndef build_tools(synapse) -> list[Dendrite]:\n    \"\"\"The clock and filesystem Effectors, a node each.\n\n    Effectors need no registration beyond this: ``attach_effector`` alone\n    makes a Dendrite service that tool's TOOL_CALLs.\n    \"\"\"\n    nodes = []\n    for effector in (clock.EFFECTOR, files.EFFECTOR):\n        node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                        dendrite_id=f\"{effector.effector_kind}-node\",\n                        role=\"worker\")\n        node.attach_effector(effector)\n        nodes.append(node)\n    return nodes\n\n\ndef build_terminal(synapse) -> Dendrite:\n    \"\"\"The Receptor that listens, on the one node that may dispatch.\n\n    Orchestrator role, and not by preference: attach_receptor and dispatch\n    both refuse a role=\"worker\" Dendrite, because a Receptor's whole job is\n    to originate TASKs. That is why interfaces get their own node.\n\n    registry_store is what makes capability routing resolve from this side -\n    the run TASK names [\"planner\"], not a neuron id.\n    \"\"\"\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"terminal-node\", heartbeat_s=0,\n                    registry_store=MemoryRegistryStore())\n    node.attach_receptor(terminal.RECEPTOR)\n    return node\n\n\ndef build_chat(synapse) -> Dendrite:\n    \"\"\"A second interface onto the same brain - a served chat page.\n\n    Its own node, for the same reason the terminal has one. Two interfaces,\n    two nodes, one brain - and the planner never learns which edge asked,\n    because both send the identical TASK.\n\n    Needs FastAPI + uvicorn: pip install 'cosmonapse[receptor]'\n    \"\"\"\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"chat-node\", heartbeat_s=0,\n                    registry_store=MemoryRegistryStore())\n    node.attach_receptor(chat.RECEPTOR)\n    return node\n\n\ndef _stop_on_signals() -> None:\n    \"\"\"Ctrl-C and SIGTERM cancel the running task instead of killing us.\n\n    The brain is not bound to its interfaces - `:quit` closes the REPL and\n    the chat page keeps serving - so a signal is the normal way it ends.\n    Cancelling rather than dying is what lets run_brain unwind every node:\n    DEREGISTER goes out, the Engram and Effectors close, the synapse closes.\n\n    add_signal_handler is Unix-only. On Windows, Ctrl-C still arrives as\n    KeyboardInterrupt (handled below) and SIGTERM is not deliverable.\n    \"\"\"\n    task = asyncio.current_task()\n    loop = asyncio.get_running_loop()\n    for sig in (signal.SIGINT, signal.SIGTERM):\n        with contextlib.suppress(NotImplementedError, AttributeError):\n            loop.add_signal_handler(sig, task.cancel)\n\n\nasync def main() -> int:\n    \"\"\"Initialise the brain: the bus, then every node on it.\"\"\"\n    _stop_on_signals()\n    url = os.environ.get(\"SYNAPSE_URL\", \"\")\n    if url:\n        synapse = await connect_synapse(url)\n    else:\n        synapse = MemorySynapse()      # in-process bus - no broker, no setup\n        await synapse.connect()\n    try:\n        return await run_brain(\n            build_memory(synapse),\n            *build_agents(synapse),\n            build_web(synapse),\n            *build_tools(synapse),\n            build_terminal(synapse),\n            build_chat(synapse),\n        )\n    except asyncio.CancelledError:\n        return 0                       # a signal: we asked for this\n    finally:\n        await synapse.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        raise SystemExit(asyncio.run(main()))\n    except KeyboardInterrupt:\n        raise SystemExit(130)\n",
  "config.py": "\"\"\"Shared configuration for the agent package.\n\nLives at the package root so every neuron / engram module can import it as\n``from config import ...`` when the example is run with ``python demo.py``.\n\"\"\"\nfrom __future__ import annotations\n\nimport os\nfrom pathlib import Path\n\nfrom dotenv import load_dotenv\n\nROOT = Path(__file__).resolve().parent          # the 14-agent/ directory\nload_dotenv(ROOT.parent / \".env\")               # cosmonapse-examples/.env\n\nNAMESPACE = \"agent\"\nMAX_STEPS = int(os.environ.get(\"AGENT_MAX_STEPS\", \"3\"))\nOUT_DIR = \"report\"\n\n\ndef hf_token() -> str:\n    token = os.environ.get(\"HF_TOKEN\", \"\")\n    if not token or token.startswith(\"hf_xxx\"):\n        raise RuntimeError(\"Set a real HF_TOKEN in cosmonapse-examples/.env\")\n    return token\n\n",
  "effector/clock.py": "\"\"\"clock - mcp-server-time (uvx) as an Effector. Tool: get_current_time.\n\nLaunched explicitly rather than with ``server=\"time\"`` so the runtime can be\npinned: ``mcp`` 2.0 renamed ``McpError`` to ``MCPError``, and mcp-server-time\nstill imports the old name, so uvx pulling the newest ``mcp`` into the\nserver's throwaway environment kills it at import (\"cannot import name\n'McpError'\"). ``--with \"mcp<2\"`` constrains that resolution. Drop the pin\nonce the server is released against mcp 2.x.\n\"\"\"\nfrom cosmonapse import Neuron\n\nfrom helpers import MCPEffector\n\nEFFECTOR = MCPEffector(\n    effector_id=\"clock-effector\", effector_kind=\"time\",\n    mcp=Neuron(source=\"mcp\", command=\"uvx\",\n               args=[\"--with\", \"mcp<2\", \"mcp-server-time\"]),\n)\n",
  "effector/fetch.py": "\"\"\"fetch - mcp-server-fetch (uvx) as an Effector. Tool: fetch a URL ->\nmarkdown/text.\n\nLaunched explicitly rather than with ``server=\"fetch\"`` to pin the runtime -\nsee effector/clock.py for why ``--with \"mcp<2\"`` is here.\n\"\"\"\nfrom cosmonapse import Neuron\n\nfrom helpers import MCPEffector\n\nEFFECTOR = MCPEffector(\n    effector_id=\"fetch-effector\", effector_kind=\"fetch\",\n    mcp=Neuron(source=\"mcp\", command=\"uvx\",\n               args=[\"--with\", \"mcp<2\", \"mcp-server-fetch\"]),\n)\n",
  "effector/files.py": "\"\"\"files - filesystem MCP server (npx) as an Effector, sandboxed to the\npackage root. Callers use the server's own tool names (write_file, ...).\"\"\"\nfrom cosmonapse import Neuron\n\nfrom config import ROOT\nfrom helpers import MCPEffector\n\nEFFECTOR = MCPEffector(\n    effector_id=\"files-effector\", effector_kind=\"filesystem\",\n    mcp=Neuron(source=\"mcp\", server=\"filesystem\", args=[str(ROOT)]),\n)\n",
  "effector/websearch.py": "\"\"\"websearch - DuckDuckGo MCP server (uvx) as an Effector. Tool: search.\"\"\"\nfrom cosmonapse import Neuron\n\nfrom helpers import MCPEffector\n\nEFFECTOR = MCPEffector(\n    effector_id=\"websearch-effector\", effector_kind=\"websearch\",\n    mcp=Neuron(source=\"mcp\", command=\"uvx\", args=[\"duckduckgo-mcp-server\"]),\n)\n",
  "engram/agent_memory.py": "\"\"\"agent-memory - the agent's working memory, plus its one host reaction.\n\nNo access neuron and no wiring helper: recall/imprint ARE Dendrite behaviour\n(``dendrite.recall(engram_id=...)`` / ``dendrite.imprint(engram_id=...)``),\nso the neurons reach this store without importing it.\n\nWhat lives here besides the store is the *host-side* reaction - mirroring\n\"answer\" imprints to disk - declared with ``@ENGRAM.host.on_imprint_signal``,\na deferred Dendrite decorator the Engram replays onto whichever Dendrite\nattaches it. Behaviour belongs in the component's module; brain.py only says\nwhich node hosts it.\n\"\"\"\nfrom cosmonapse import InMemoryEngram\n\nfrom config import ROOT\n\nENGRAM_ID = \"agent-memory\"\n\nENGRAM = InMemoryEngram(engram_id=ENGRAM_ID, engram_kind=\"context\")\n\n\n@ENGRAM.host.on_imprint_signal\nasync def persist_answers(sig):\n    \"\"\"Mirror \"answer\" imprints carrying a path to disk (files Effector).\n\n    ``ENGRAM.dendrite`` is the node this Engram was attached to - the\n    memory-side twin of ``AXON.dendrite`` - so the handler can call a tool\n    without brain.py handing it a reference.\n    \"\"\"\n    entry = sig.payload.get(\"entry\") or {}\n    path = (sig.meta or {}).get(\"path\")\n    if not (path and \"answer\" in (entry.get(\"tags\") or [])):\n        return\n    out = await ENGRAM.dendrite.call_tool(\n        effector_id=\"files-effector\", tool=\"write_file\",\n        args={\"path\": str(ROOT / path), \"content\": entry.get(\"content\", \"\")},\n        deadline_ms=30_000)\n    if out.error:\n        raise RuntimeError(f\"answer mirror failed: {out.error}\")\n",
  "helpers.py": "\"\"\"helpers - the two shared pieces that are not themselves components.\n\nEverything under neurons/, effector/, engram/ and receptors/ declares ONE\ncomponent per module; brain.py declares deployment. This file is what is\nleft over: an Effector *base class* several tools share, and the TASK input\nboth interfaces build. Keeping them here means no folder contains a module\nthat is not a component, and no component module imports a sibling.\n\n    MCPEffector      wrap a Neuron(source=\"mcp\", ...) as an Effector\n    task_input       a goal -> the chain state a run starts from\n    result_of        the FINAL payload's result\n    memory_summary   what the agent remembers this session\n\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Any, Callable\n\nfrom cosmonapse import Effector, Neuron, ToolOutcome, new_trace_id\n\nfrom config import MAX_STEPS\n\n# ---------------------------------------------------------------------------\n# Tools: one adapter, four Effectors\n# ---------------------------------------------------------------------------\n\n#: (tool, args) -> (server_tool, server_args); raise for bad args.\nToolShaper = Callable[[str, dict[str, Any]], tuple[str, dict[str, Any]]]\n\n\nclass MCPEffector(Effector):\n    \"\"\"Proxies TOOL_CALL onto an underlying MCP-server Neuron, through an\n    optional ``shape`` translation (model-facing name -> server name).\n\n    One shared adapter so websearch.py / fetch.py / clock.py / files.py are\n    each a single Neuron(...) call: TOOL_CALL/TOOL_RESULT servicing is a\n    built-in SDK feature (Dendrite.attach_effector), so there is no\n    @AXON.host.on_tool_call / hand-rolled tool protocol left to write per\n    tool. This example's callers speak the servers' own tool names (search,\n    fetch, get_current_time, write_file), so no ``shape`` translation is\n    wired here - the hook exists for when a model-facing name must be mapped\n    onto a server name (see 15-claude-harness). The underlying Neuron owns\n    the subprocess; ``connect()`` warms it at Dendrite.start() so the first\n    real TOOL_CALL is not billed for the spawn, and close() tears it down.\n    \"\"\"\n\n    def __init__(\n        self,\n        *,\n        effector_id: str,\n        effector_kind: str,\n        mcp: Neuron,\n        shape: ToolShaper | None = None,\n        capabilities: list[str] | None = None,\n    ) -> None:\n        self.effector_id = effector_id\n        self.effector_kind = effector_kind\n        # empty = proxy: serve whatever the server (or shaper) accepts\n        self.capabilities: list[str] = capabilities or []\n        self._mcp = mcp\n        self._shape = shape\n\n    async def connect(self) -> None:\n        \"\"\"Spawn + initialise the MCP subprocess NOW, at Dendrite.start().\n\n        The Neuron would otherwise spawn lazily on the first TOOL_CALL -\n        and a cold ``npx``/``uvx`` start (package download, node boot)\n        routinely runs past a caller's ``deadline_ms``, surfacing as an\n        EffectorTimeout that looks like a broken tool. Listing the tools\n        forces the handshake here instead, where a genuine launch failure\n        also fails start() loudly rather than timing out later.\n        \"\"\"\n        await self._mcp({\"__list_tools__\": True}, [])\n\n    async def close(self) -> None:\n        await self._mcp.aclose()\n\n    async def invoke(\n        self,\n        tool: str,\n        args: dict[str, Any],\n        *,\n        call_id: str | None = None,\n        deadline_ms: int | None = None,\n        trace_id: str | None = None,\n    ) -> ToolOutcome:\n        server_tool, server_args = tool, dict(args or {})\n        if self._shape is not None:\n            try:\n                server_tool, server_args = self._shape(tool, server_args)\n            except Exception as exc:  # noqa: BLE001 - bad args, not a fault\n                return ToolOutcome(tool=tool, call_id=call_id,\n                                   error=f\"{type(exc).__name__}: {exc}\")\n        out = await self._mcp({\"tool\": server_tool, \"arguments\": server_args}, [])\n        if out.get(\"is_error\"):\n            return ToolOutcome(\n                tool=tool, call_id=call_id,\n                error=str(out.get(\"response\") or f\"{tool} failed\"),\n            )\n        return ToolOutcome(tool=tool, call_id=call_id, result=out)\n\n\n# ---------------------------------------------------------------------------\n# Interfaces: what a run starts from, and how its FINAL is read\n# ---------------------------------------------------------------------------\n\ndef task_input(goal: str, max_steps: int = MAX_STEPS) -> dict:\n    \"\"\"A goal -> the TASK input the planner expects. One dispatch's worth.\n\n    The chain state ({\"goal\",\"tag\",\"step\",\"max_steps\",\"steps\",\"sources\"}) is\n    the agent's whole protocol with itself - it rides the TASK inputs and is\n    echoed through every output, so no node holds run state. Building it is\n    therefore the interface's job, and it is identical whichever edge you\n    came in through.\n\n    ``tag`` labels this run's engram entries. It is a fresh id per goal and\n    NOT the trace id: a Receptor does not choose the trace (dispatch does),\n    and the planner only ever uses ``tag`` as an engram key, so the two need\n    not match.\n    \"\"\"\n    return {\"goal\": goal.strip(), \"tag\": new_trace_id(), \"step\": 1,\n            \"max_steps\": max_steps, \"steps\": [], \"sources\": []}\n\n\ndef result_of(sig) -> dict:\n    \"\"\"The FINAL payload's result - what the planner concluded the run with.\"\"\"\n    return (sig.payload or {}).get(\"result\") or {}\n\n\ndef memory_summary(engram) -> dict:\n    \"\"\"What the agent remembers this session.\n\n    Only meaningful when the engram backend lives in THIS process - i.e. an\n    in-process synapse, or the process that stood the engram host up.\n    \"\"\"\n    entries = list(getattr(engram, \"_entries\", {}).values())\n    kinds = [(e.tags or [\"?\"])[0] for e in entries]\n    return {\n        \"entries\": len(entries),\n        \"remembered_answers\": kinds.count(\"answer\"),\n        \"research_notes\": kinds.count(\"research\"),\n        \"code_snapshots\": kinds.count(\"code\"),\n    }\n",
  "neurons/model/coding.py": "\"\"\"coding - a STOCK LLM Neuron; everything else is decorator-specified.\n\n    @AXON.before_task      RECALL the research notes via the Dendrite\n    @AXON.detects_output   extract the code, save it (files Effector),\n                           IMPRINT it, echo the chain state\n\n    @AXON.host.on_agent_output(neuron=\"coding\")   THE CHAIN: creates the\n    next planner TASK on the hosting Dendrite (deferred host decorator).\n\"\"\"\nimport re\n\nfrom cosmonapse import Axon\nfrom cosmonapse.envelope import ambient_trace\n\nfrom config import OUT_DIR, ROOT, hf_token\nfrom engram.agent_memory import ENGRAM_ID\n\nSYSTEM = (\n    \"You are a senior Python engineer. Write ONE small, complete, runnable \"\n    \"script that satisfies the subtask, honouring the research notes. Standard \"\n    \"library only. Reply with exactly one fenced code block:\\n\"\n    \"```python\\n<the script>\\n```\\nNo prose before or after.\"\n)\n\n_FENCE = re.compile(r\"```(?:python|py)?\\s*\\n(.*?)```\", re.S)\n_PENDING: dict[str, dict] = {}      # per-trace state: before_task -> detector\n\n\ndef _extract_code(text):\n    m = _FENCE.search(text or \"\")\n    return (m.group(1).strip() + \"\\n\") if m else (text or \"\").strip() + \"\\n\"\n\n\n#: The Axon IS the model: Axon.huggingface() pairs the neuron_id with\n#: an HF-router chat source, so the source lives on the declaration\n#: rather than in a separately-built neuron_fn.\nAXON = Axon.huggingface(\n    neuron_id=\"coding\",\n    capabilities=[\"coding\"],\n    endpoint=\"https://router.huggingface.co\",\n    model=\"Qwen/Qwen2.5-Coder-32B-Instruct\",\n    use_chat_api=True,\n    max_new_tokens=1024,\n    temperature=0.2,\n    recognize=False,\n    api_key=\"dummy\",\n)\n\n\n@AXON.before_task\nasync def ground(input):\n    \"\"\"Recall this run's notes (dendrite.recall), shape the prompt.\"\"\"\n    tid, _ = ambient_trace()\n    res = await AXON.dendrite.recall(\n        engram_id=ENGRAM_ID,\n        query={\"tag\": input.get(\"tag\", \"\"), \"top_k\": 50},\n        deadline_ms=2000,\n    )\n    grounding = \"\\n\\n\".join(\n        h.entry[\"content\"] for h in res.hits\n        if \"research\" in h.entry.get(\"tags\", [])\n    ) or \"(no notes)\"\n    _PENDING[tid] = dict(input)\n    return {\"messages\": [\n        {\"role\": \"system\", \"content\": SYSTEM},\n        {\"role\": \"user\", \"content\":\n            f\"Subtask: {input['task']}\\n\\nResearch notes:\\n{grounding}\"},\n    ]}\n\n\n@AXON.detects_output\nasync def save_and_remember(raw):\n    \"\"\"Extract the script, write it with MY filesystem tool, imprint it.\"\"\"\n    tid, _ = ambient_trace()\n    st = _PENDING.pop(tid, {})\n    code = _extract_code(raw.get(\"response\"))\n\n    code_path = f\"{OUT_DIR}/solution.py\"\n    write = await AXON.dendrite.call_tool(\n        effector_id=\"files-effector\", tool=\"write_file\",\n        args={\"path\": str(ROOT / code_path), \"content\": code},\n        deadline_ms=30_000)\n    if write.error:\n        raise RuntimeError(f\"write_file error: {write.error}\")\n    await AXON.dendrite.imprint(\n        engram_id=ENGRAM_ID, op=\"append\",\n        entry={\"content\": f\"[code]\\n{code}\", \"tags\": [\"code\", st.get(\"tag\", \"\")]},\n        await_ack=True, deadline_ms=2000,\n    )\n    return {\"code\": code, \"code_path\": code_path,\n            \"goal\": st.get(\"goal\"), \"tag\": st.get(\"tag\"),\n            \"step\": st.get(\"step\"), \"max_steps\": st.get(\"max_steps\"),\n            \"steps\": st.get(\"steps\") or [], \"sources\": st.get(\"sources\") or []}\n\n\n@AXON.host.on_agent_output(neuron=\"coding\")\nasync def chain(sig):\n    \"\"\"The coding node's chain behaviour - hand back to the planner.\"\"\"\n    out = sig.payload.get(\"output\", {})\n    await AXON.dendrite.dispatch_task(\n        capabilities=[\"planner\"],\n        input={\"goal\": out.get(\"goal\"), \"tag\": out.get(\"tag\"),\n               \"step\": (out.get(\"step\") or 0) + 1,\n               \"max_steps\": out.get(\"max_steps\") or 0,\n               \"steps\": out.get(\"steps\") or [],\n               \"sources\": out.get(\"sources\") or []},\n        trace_id=sig.trace_id, parent_id=sig.id,\n    )\n",
  "neurons/model/planner.py": "\"\"\"planner - a STOCK LLM Neuron; everything else is decorator-specified.\n\n    @AXON.before_task      cache check + progress recall (dendrite.recall),\n                           situate (clock Effector), build the prompt\n    @AXON.detects_output   parse + validate the route JSON, echo the chain state\n\n    @AXON.host.on_agent_output(neuron=\"planner\")   THE CHAIN: picks the\n    decision up and CREATES the next TASK (research / coding) - or, on\n    finish, assembles the report from the engram, imprints it, and emits\n    FINAL to conclude the trace (deferred host decorator).\n\nChain state ({\"goal\",\"tag\",\"step\",\"max_steps\",\"steps\",\"sources\"}) rides the\nTASK inputs and is echoed through each output, so no node holds run state -\nprogress itself is recalled from the engram.\n\"\"\"\nimport json\nimport re\n\nfrom cosmonapse import Axon\nfrom cosmonapse.envelope import ambient_trace\n\nfrom config import OUT_DIR, ROOT, hf_token\nfrom engram.agent_memory import ENGRAM_ID\n\nSYSTEM = (\n    \"You are a supervisor that delegates to two specialists by CAPABILITY:\\n\"\n    '  \"research\" - searches the web and writes findings\\n'\n    '  \"coding\"   - writes a runnable Python script from findings\\n\\n'\n    \"Pick the SINGLE best next subtask, or finish when the goal is met:\\n\"\n    '  {\"route\": \"research\", \"task\": \"<what to find out / search query>\"}\\n'\n    '  {\"route\": \"coding\",   \"task\": \"<what script to write>\"}\\n'\n    '  {\"route\": \"finish\",   \"task\": \"\"}\\n\\n'\n    \"Research first (at most twice). As soon as research notes exist and the \"\n    \"goal asks for a script/program/CLI, route \\\"coding\\\". Only finish after \"\n    \"any requested code is written. Reply with EXACTLY ONE JSON object.\"\n)\n\n_JSON_OBJ = re.compile(r\"\\{.*?\\}\", re.S)\n_CHAIN_KEYS = (\"goal\", \"tag\", \"step\", \"max_steps\", \"steps\", \"sources\", \"now\")\n_PENDING: dict[str, dict] = {}      # per-trace state: before_task -> detector\n\n\ndef _first_json(text):\n    m = _JSON_OBJ.search(text or \"\")\n    if not m:\n        return None\n    try:\n        return json.loads(m.group(0))\n    except json.JSONDecodeError:\n        return None\n\n\n#: The Axon IS the model: Axon.huggingface() pairs the neuron_id with\n#: an HF-router chat source, so the source lives on the declaration\n#: rather than in a separately-built neuron_fn.\nAXON = Axon.huggingface(\n    neuron_id=\"planner\",\n    capabilities=[\"planner\"],\n    endpoint=\"https://router.huggingface.co\",\n    model=\"meta-llama/Llama-3.1-8B-Instruct\",\n    use_chat_api=True,\n    max_new_tokens=1024,\n    temperature=0.2,\n    recognize=False,\n    api_key=\"dummy\",\n)\n\n\n@AXON.before_task\nasync def situate(input):\n    \"\"\"Cache check + progress recall + clock grounding, then the prompt.\"\"\"\n    tid, _ = ambient_trace()\n    d = AXON.dendrite\n\n    # A previously remembered answer short-circuits the whole run.\n    cached = await d.recall(engram_id=ENGRAM_ID,\n                            query={\"merge_key\": f\"answer:{input['goal']}\"},\n                            deadline_ms=2000)\n    if cached.hits:\n        _PENDING[tid] = {**input, \"cached\": cached.hits[0].entry[\"content\"]}\n        return {\"messages\": [{\"role\": \"user\", \"content\": 'Reply with {}'}]}\n\n    # Progress is not carried by any node - it is recalled from the engram.\n    done = await d.recall(engram_id=ENGRAM_ID,\n                          query={\"tag\": input[\"tag\"], \"top_k\": 50},\n                          deadline_ms=2000)\n    notes = sum(1 for h in done.hits if \"research\" in h.entry.get(\"tags\", []))\n    coded = any(\"code\" in h.entry.get(\"tags\", []) for h in done.hits)\n\n    # The clock only *grounds* the prompt - it is not load-bearing, so a\n    # dead Effector degrades the answer instead of ending the run. A tool\n    # error rides its TOOL_RESULT and never terminates the TASK by itself;\n    # what would end it is raising here, in the hook. Compare research and\n    # coding, which DO raise: without a search result or a written file\n    # there is nothing for those neurons to be right about.\n    clock = await d.call_tool(effector_id=\"clock-effector\",\n                              tool=\"get_current_time\",\n                              args={\"timezone\": \"UTC\"}, deadline_ms=30_000)\n    if clock.error:\n        print(f\"! clock unavailable ({clock.error}) - planning without it\")\n        now = \"unknown\"\n    else:\n        out = clock.result or {}\n        now = out.get(\"response\") or str(out.get(\"result\"))\n    _PENDING[tid] = {**input, \"now\": now, \"notes\": notes, \"code_written\": coded}\n\n    state = (f\"research notes: {notes}; \"\n             f\"code written: {'yes' if coded else 'no'}\")\n    return {\"messages\": [\n        {\"role\": \"system\", \"content\": SYSTEM},\n        {\"role\": \"user\", \"content\": (\n            f\"Goal: {input['goal']}\\nUTC time: {now}\\n\"\n            f\"Step {input['step']}/{input['max_steps']}\\n\"\n            f\"Progress so far -> {state}\\n\\nNext subtask?\"\n        )},\n    ]}\n\n\n@AXON.detects_output\ndef decide(raw):\n    \"\"\"Parse the model's JSON; force finish past max_steps; echo the chain.\"\"\"\n    tid, _ = ambient_trace()\n    st = _PENDING.pop(tid, {})\n    chain = {k: st.get(k) for k in _CHAIN_KEYS}\n    if st.get(\"cached\"):\n        return {\"route\": \"finish\", \"task\": \"\", \"cached\": st[\"cached\"], **chain}\n\n    decision = _first_json(raw.get(\"response\")) or {}\n    route = (decision.get(\"route\") or \"\").lower()\n    task = (decision.get(\"task\") or \"\").strip()\n    if st.get(\"step\", 1) > st.get(\"max_steps\", 0):\n        route, task = \"finish\", \"\"\n    elif route not in {\"research\", \"coding\", \"finish\"}:\n        route, task = (\n            (\"research\", st.get(\"goal\", \"\")) if not st.get(\"notes\")\n            else (\"coding\", st.get(\"goal\", \"\")) if not st.get(\"code_written\")\n            else (\"finish\", \"\")\n        )\n    elif (route == \"research\" and st.get(\"notes\")\n          and not st.get(\"code_written\")\n          and st.get(\"step\", 1) >= st.get(\"max_steps\", 0)):\n        # Last step and still no code: a small model loves to keep\n        # researching - spend the final step writing the script instead.\n        route, task = \"coding\", st.get(\"goal\", \"\")\n    return {\"route\": route, \"task\": task, **chain}\n\n\n@AXON.host.on_agent_output(neuron=\"planner\")\nasync def chain(sig):\n    \"\"\"The planner node's chain behaviour - the hosting Dendrite picks the\n    decision up and creates the next TASK, or concludes the trace.\"\"\"\n    node = AXON.dendrite\n    d = sig.payload.get(\"output\", {})\n    route, goal, tag = d.get(\"route\"), d.get(\"goal\"), d.get(\"tag\")\n\n    if route in (\"research\", \"coding\"):\n        steps = (d.get(\"steps\") or []) + [{\"route\": route,\n                                           \"task\": d.get(\"task\", \"\")}]\n        await node.dispatch_task(\n            capabilities=[route],\n            input={\"task\": d.get(\"task\", \"\"), \"goal\": goal, \"tag\": tag,\n                   \"step\": d.get(\"step\", 1),\n                   \"max_steps\": d.get(\"max_steps\", 0),\n                   \"steps\": steps, \"sources\": d.get(\"sources\") or []},\n            trace_id=sig.trace_id, parent_id=sig.id,\n        )\n        return\n\n    # finish - straight from the cache ...\n    if d.get(\"cached\"):\n        await node.emit_final(\n            trace_id=sig.trace_id, parent_id=sig.id, neuron=\"planner\",\n            result={\"report\": d[\"cached\"], \"source\": \"memory\",\n                    \"steps\": [], \"trace_id\": tag},\n        )\n        return\n\n    # ... or assembled from this run's engram entries.\n    got = await node.recall(engram_id=ENGRAM_ID,\n                            query={\"tag\": tag, \"top_k\": 50},\n                            deadline_ms=2000,\n                            trace_id=sig.trace_id, parent_id=sig.id)\n    notes = [h.entry[\"content\"] for h in got.hits\n             if \"research\" in h.entry.get(\"tags\", [])]\n    code = next((h.entry[\"content\"].removeprefix(\"[code]\\n\")\n                 for h in got.hits if \"code\" in h.entry.get(\"tags\", [])),\n                None)\n    code_path = f\"{OUT_DIR}/solution.py\" if code else None\n\n    # The report is the ANSWER, not the artefact: research prose in full,\n    # and for the code a pointer to where the coding Neuron actually saved\n    # it. The script is already on disk next to answer.md, so inlining it\n    # here would only duplicate it - and a chat turn wants the finding plus\n    # a path, not a screenful of Python.\n    parts = [f\"# {goal}\", f\"_generated {d.get('now')}_\", \"\"]\n    for n, note in enumerate(notes, 1):\n        parts += [f\"## Research note {n}\", note, \"\"]\n    if code:\n        parts += [\"## Generated solution\",\n                  f\"Saved to `{ROOT / code_path}`\",\n                  f\"({len(code.splitlines())} lines, written by the coding \"\n                  f\"Neuron through the files Effector.)\", \"\"]\n    sources = d.get(\"sources\") or []\n    if sources:\n        parts += [\"## Sources\", *[f\"- {url}\" for url in sources], \"\"]\n    report = \"\\n\".join(parts)\n    report_path = f\"{OUT_DIR}/answer.md\"\n\n    await node.imprint(engram_id=ENGRAM_ID, op=\"upsert\",\n                       merge_key=f\"answer:{goal}\",\n                       entry={\"content\": report, \"tags\": [\"answer\"]},\n                       meta={\"path\": report_path},\n                       await_ack=True, deadline_ms=2000,\n                       trace_id=sig.trace_id, parent_id=sig.id)\n    await node.emit_final(\n        trace_id=sig.trace_id, parent_id=sig.id, neuron=\"planner\",\n        result={\"report\": report, \"code_path\": code_path,\n                \"report_path\": report_path, \"source\": \"web\",\n                \"steps\": d.get(\"steps\") or [],\n                \"sources\": d.get(\"sources\") or [], \"trace_id\": tag},\n    )\n\n",
  "neurons/model/research.py": "\"\"\"research - a STOCK LLM Neuron; everything else is decorator-specified.\n\n    @AXON.before_task      gather web context (websearch + fetch Effectors)\n    @AXON.detects_output   strip the note, IMPRINT it, echo the chain state\n\n    @AXON.host.on_agent_output(neuron=\"research\")   THE CHAIN: creates the\n    next planner TASK on the hosting Dendrite (deferred host decorator).\n\"\"\"\nimport re\n\nfrom cosmonapse import Axon\nfrom cosmonapse.envelope import ambient_trace\n\nfrom config import hf_token\nfrom engram.agent_memory import ENGRAM_ID\n\nSYSTEM = (\n    \"You are a research specialist. Using ONLY the supplied web context, write \"\n    \"tight, factual notes that answer the subtask: key facts, constraints, and \"\n    \"any concrete API/usage details a programmer would need. Cite URLs only if \"\n    \"they appear in the context. Do not invent facts.\"\n)\n\n_URL = re.compile(r\"https?://[^\\s)\\]]+\")\n_PENDING: dict[str, dict] = {}      # per-trace state: before_task -> detector\n\n\n#: How many search hits to try fetching before giving up on full text.\nMAX_FETCH_ATTEMPTS = 3\n\n\ndef _urls(text, limit=MAX_FETCH_ATTEMPTS):\n    \"\"\"Candidate pages from the search result, in rank order, deduped.\"\"\"\n    seen, out = set(), []\n    for m in _URL.finditer(text or \"\"):\n        url = m.group(0).rstrip(\".,);]\")\n        if url not in seen:\n            seen.add(url)\n            out.append(url)\n        if len(out) >= limit:\n            break\n    return out\n\n\n#: The Axon IS the model: Axon.huggingface() pairs the neuron_id with\n#: an HF-router chat source, so the source lives on the declaration\n#: rather than in a separately-built neuron_fn.\nAXON = Axon.huggingface(\n    neuron_id=\"research\",\n    capabilities=[\"research\"],\n    endpoint=\"https://router.huggingface.co\",\n    model=\"meta-llama/Llama-3.3-70B-Instruct\",\n    use_chat_api=True,\n    max_new_tokens=1024,\n    temperature=0.2,\n    recognize=False,\n    api_key=\"dummy\",\n)\n\n\n@AXON.before_task\nasync def gather(input):\n    \"\"\"Gather web context via MY tools, shaped into the prompt.\"\"\"\n    tid, _ = ambient_trace()\n    d = AXON.dendrite\n    task = input[\"task\"]\n\n    search_out = await d.call_tool(effector_id=\"websearch-effector\",\n                                   tool=\"search\",\n                                   args={\"query\": task, \"max_results\": 5},\n                                   deadline_ms=60_000)\n    if search_out.error:\n        raise RuntimeError(f\"websearch error: {search_out.error}\")\n    search = search_out.result or {}\n    ctx = search.get(\"response\", \"\")[:1500]\n    # Full page text is a BONUS on top of the search snippets, so an\n    # unreachable page is skipped rather than fatal - plenty of sites answer\n    # a server-side fetch with 403, a paywall, or a robots.txt refusal, and\n    # losing the whole run to the luck of the first search hit is not a\n    # research strategy. Walk the hits until one comes back; if none does,\n    # the snippets alone still ground the note.\n    #\n    # The search itself DOES raise: with neither snippets nor a page there\n    # is nothing for this Neuron to be right about.\n    sources = []\n    for url in _urls(search.get(\"response\")):\n        page_out = await d.call_tool(effector_id=\"fetch-effector\",\n                                     tool=\"fetch\",\n                                     args={\"url\": url, \"max_length\": 2500},\n                                     deadline_ms=60_000)\n        if page_out.error:\n            print(f\"! skipping {url} ({page_out.error})\")\n            continue\n        page = page_out.result or {}\n        ctx += f\"\\n\\n[page {url}]\\n{page.get('response', '')[:2000]}\"\n        sources.append(url)\n        break\n    if not sources:\n        ctx += \"\\n\\n[no page could be fetched - snippets only]\"\n\n    _PENDING[tid] = {**input, \"found\": sources}\n    return {\"messages\": [\n        {\"role\": \"system\", \"content\": SYSTEM},\n        {\"role\": \"user\", \"content\": f\"Subtask: {task}\\n\\nWeb context:\\n{ctx}\"},\n    ]}\n\n\n@AXON.detects_output\nasync def note_and_imprint(raw):\n    \"\"\"Shape the note, remember it (dendrite.imprint), echo the chain.\"\"\"\n    tid, _ = ambient_trace()\n    st = _PENDING.pop(tid, {})\n    note = (raw.get(\"response\") or \"\").strip()\n    await AXON.dendrite.imprint(\n        engram_id=ENGRAM_ID, op=\"append\",\n        entry={\"content\": note, \"tags\": [\"research\", st.get(\"tag\", \"\")]},\n        await_ack=True, deadline_ms=2000,\n    )\n    return {\"note\": note,\n            \"goal\": st.get(\"goal\"), \"tag\": st.get(\"tag\"),\n            \"step\": st.get(\"step\"), \"max_steps\": st.get(\"max_steps\"),\n            \"steps\": st.get(\"steps\") or [],\n            \"sources\": (st.get(\"sources\") or []) + (st.get(\"found\") or [])}\n\n\n@AXON.host.on_agent_output(neuron=\"research\")\nasync def chain(sig):\n    \"\"\"The research node's chain behaviour - hand back to the planner.\"\"\"\n    out = sig.payload.get(\"output\", {})\n    await AXON.dendrite.dispatch_task(\n        capabilities=[\"planner\"],\n        input={\"goal\": out.get(\"goal\"), \"tag\": out.get(\"tag\"),\n               \"step\": (out.get(\"step\") or 0) + 1,\n               \"max_steps\": out.get(\"max_steps\") or 0,\n               \"steps\": out.get(\"steps\") or [],\n               \"sources\": out.get(\"sources\") or []},\n        trace_id=sig.trace_id, parent_id=sig.id,\n    )\n",
  "receptors/chat.py": "\"\"\"chat - a ChatReceptor: one browser turn becomes a TASK.\n\n    pip install 'cosmonapse[receptor]'\n    python brain.py                 # served alongside the terminal REPL\n    open http://127.0.0.1:8000\n\nSame brain, second interface. The Neuron never learns which edge asked:\nterminal.py and this file build the identical TASK, so nothing under\nneurons/ changed to grow a chat window.\n\nWhat comes back\n---------------\nThe page shows the trace's FINAL report, which is the *answer* and not the\nartefact: research notes in full, and for code the path the coding Neuron\nsaved it to rather than a screenful of Python. That shaping lives in the\nplanner's assemble step (neurons/model/planner.py), not here - both edges\nand the on-disk answer.md then agree by construction, and no rendering hook\nis needed on this side.\n\nWhy no history\n--------------\n``history_turns=0``: this brain's memory is the Engram, not the transport.\nAsk the same goal twice and the planner short-circuits on a remembered\nanswer (``source: \"memory\"``) - a per-browser-session transcript would sit\nalongside that and mean something different. Raise it if you grow a Neuron\nthat reads ``history``.\n\nVoice is client side - the browser's Web Speech API. No audio dependency\nhere, no audio on the wire.\n\nBuilt with no dendrite= on purpose; brain.py binds it.\n\"\"\"\nfrom cosmonapse import ChatReceptor\n\nfrom helpers import task_input\n\nRECEPTOR = ChatReceptor(\n    capabilities=[\"planner\"],       # routed, not addressed - see terminal.py\n    receptor_id=\"agent-chat\",\n    title=\"Cosmonapse Agent\",\n    greeting=\"Give me a goal - I'll research it, and write the code if it needs any.\",\n    voice=True,\n    history_turns=0,\n    scope=\"terminal\",               # wake for FINAL / ERROR only\n    finalize=False,                 # ... and don't auto-promote a worker's\n                                    # AGENT_OUTPUT into one - the planner node\n                                    # owns FINAL. See terminal.py.\n    timeout_s=600.0,\n    max_timeout_s=900.0,\n    host=\"127.0.0.1\",\n    port=8000,\n)\n\n\n@RECEPTOR.on_input\ndef build(raw):\n    \"\"\"The turn -> the run's chain state. Replaces the default wrapping.\"\"\"\n    goal = raw[\"message\"] if isinstance(raw, dict) else raw\n    return task_input(str(goal))\n",
  "receptors/terminal.py": "\"\"\"terminal - a CliReceptor: a goal typed at a shell becomes a TASK.\n\n    python brain.py                                   # the brain, plus a REPL\n    python brain.py \"Research X, then write a CLI\"    # one-shot\n    python brain.py --stream \"...\"                    # watch the chain live\n    python brain.py memory                            # what it remembers\n\nThis replaces the hand-rolled cli.py the old 14-agent-cli example carried:\nargparse tree, REPL, and result formatting are all derived from the command\nfunctions below. A command function returns the TASK *input* - that is the\nwhole contract.\n\nTwo things are not defaults and both matter for a choreographed brain:\n\n    capabilities=[\"planner\"]  the run is routed, not addressed - the edge\n                              names a capability and the registry finds the\n                              planner. Swap the planner out and this file\n                              does not change.\n    scope=\"terminal\"          resolve on FINAL / ERROR only. The planner\n                              node emits FINAL after assembling the report;\n                              every AGENT_OUTPUT before it is mid-flight.\n    finalize=False            do NOT auto-promote a worker's AGENT_OUTPUT to\n                              FINAL. Left unset it defaults to promoting,\n                              which would end the run one step in with the\n                              planner's routing decision as \"the answer\".\n                              The planner node owns FINAL here, not a worker.\n\nBuilt with no dendrite= on purpose; brain.py binds it.\n\"\"\"\nfrom cosmonapse import CliReceptor, SignalType\n\nfrom config import MAX_STEPS\nfrom engram import agent_memory\nfrom helpers import memory_summary, result_of, task_input\n\nRECEPTOR = CliReceptor(\n    capabilities=[\"planner\"],\n    prog=\"agent\",\n    description=\"Drive the choreographed Cosmonapse agent from a terminal.\",\n    banner=\"agent - type a goal, `memory`, :help, or :quit\",\n    prompt=\"goal> \",\n    scope=\"terminal\",\n    finalize=False,\n    timeout_s=600.0,\n)\n\n\n@RECEPTOR.command(help=\"run the agent on a goal\")\ndef run(goal: str, max_steps: int = MAX_STEPS):\n    \"\"\"ONE capability-routed TASK goes out; the nodes chain the rest.\"\"\"\n    return task_input(goal, max_steps)\n\n\n@RECEPTOR.command(\"memory\", local=True, help=\"what the agent remembers\")\ndef memory():\n    \"\"\"local=True: answered right here, nothing crosses the wire.\"\"\"\n    return memory_summary(agent_memory.ENGRAM)\n\n\n@RECEPTOR.on_signal(SignalType.TOOL_CALL)\nasync def show_tool(sig):\n    \"\"\"The progress channel - observation only, nothing here changes the trace.\"\"\"\n    print(f\"  . {(sig.payload or {}).get('tool', '?')}\")\n\n\n@RECEPTOR.on_result\ndef render(sig):\n    \"\"\"FINAL -> what the terminal prints: the report, then the artefacts.\"\"\"\n    result = result_of(sig)\n    steps = result.get(\"steps\") or []\n    lines = [(result.get(\"report\") or \"\").rstrip(), \"\",\n             f\"--- {len(steps)} step(s), source: {result.get('source', '?')}\"]\n    if result.get(\"report_path\"):\n        lines.append(f\"report : {result['report_path']}\")\n    if result.get(\"code_path\"):\n        lines.append(f\"code   : {result['code_path']}\")\n    return \"\\n\".join(lines)\n"
};
